// The SDK driver (server/paypal-sdk.js, PayPal's own @paypal/paypal-server-sdk, generated by APIMATIC) behind the same interface as the fetch client: the same requests reach
// PayPal, the same errors come back as the same codes, sandbox only, and nothing secret leaks. A fake PayPal answers through an axios adapter, so no network is used.
import assert from 'node:assert'
import { Readable } from 'node:stream'
import { createSdkPayPal } from '../paypal-sdk.js'
import { createPayPal, PayPalError, NOT_SET_UP, SANDBOX_BASE } from '../paypal.js'
import { createFakePayPal } from './fakepaypal.js'
import { adapterFor as adapterWith } from './sdk-transport.js'

const ID = 'sdk-test-id-' + 'a'.repeat(20); const SECRET = 'sdk-test-secret-' + 'b'.repeat(20) // throwaway
let n = 0; const ok = (c, m) => { assert.ok(c, m); n++ }; const eq = (a, b, m) => { assert.deepStrictEqual(a, b, m); n++ }
const rej = async (p, code, m) => { try { await p } catch (e) { eq(e instanceof PayPalError ? e.code : e.name + ':' + e.message, code, m); return e } assert.fail('should have failed: ' + m) }
const logs = []; let fake; let calls = []
const adapterFor = f => async config => adapterWith(f, calls)(config) // keep recording into the current calls array
const fresh = (o = {}) => { fake = createFakePayPal({ clientId: ID, clientSecret: SECRET }); calls = []; logs.length = 0; return createSdkPayPal({ clientId: ID, clientSecret: SECRET, transport: adapterFor(fake), log: m => logs.push(m), ...o }) }
const apiCalls = () => calls.filter(c => c.path !== '/v1/oauth2/token')
const ORDER = { cents: 2500, currency: 'USD', description: 'Logo design invoice', requestId: 'vespr-pay-0123456789abcdef', returnUrl: 'https://vespr.example/api/pay/return', cancelUrl: 'https://vespr.example/api/pay/cancel' }

// the driver says what it is, is sandbox only, and says plainly when it is not set up
{
  const p = fresh(); eq([p.driver, p.mode, p.baseUrl, p.configured], ['sdk', 'sandbox', SANDBOX_BASE, true]); eq(createPayPal({ clientId: ID, clientSecret: SECRET, fetchImpl: async () => { throw new Error('x') } }).driver, 'fetch')
  const off = createSdkPayPal({ clientId: '', clientSecret: '', log: () => {} }); eq(off.configured, false); const e = await rej(off.createOrder(ORDER), 'not_set_up'); eq(e.message, NOT_SET_UP); await rej(off.getOrder('ORDER1234567890AB'), 'not_set_up'); await rej(off.captureOrder('ORDER1234567890AB'), 'not_set_up'); await rej(off.refundCapture('CAP1234567', { cents: 100 }), 'not_set_up')
  eq(createSdkPayPal({ clientId: ID, clientSecret: SECRET, allowLive: false, log: () => {} }).mode, 'sandbox', 'live is not reachable without the explicit flag and the live address')
}
// create: the same request body as the fetch client sends, with PayPal-Request-Id; the payer link on paypal.com; a replay returns the same order
{
  const p = fresh(); const o = await p.createOrder({ ...ORDER, description: 'Logo\u0000 design\ninvoice ' + 'x'.repeat(200), referenceId: 'ref-1', customId: 'cust-1' })
  ok(/^FAKEORD\d+XYZ$/.test(o.id) && o.status === 'PAYER_ACTION_REQUIRED' && o.approveUrl.startsWith('https://www.sandbox.paypal.com/checkoutnow?token=' + o.id), 'order id, status and the sandbox payer link')
  const c = apiCalls()[0]; eq([c.method, c.path, c.headers['paypal-request-id']], ['POST', '/v2/checkout/orders', ORDER.requestId]); const b = JSON.parse(c.body); const pu = b.purchase_units[0]
  eq(b.intent, 'CAPTURE'); eq(pu.amount, { currency_code: 'USD', value: '25.00' }); eq([pu.reference_id, pu.custom_id], ['ref-1', 'cust-1']); ok(pu.description.length === 127 && !/[\u0000\n]/.test(pu.description))
  const ctx = b.payment_source.paypal.experience_context; eq([ctx.brand_name, ctx.shipping_preference, ctx.landing_page, ctx.user_action, ctx.payment_method_preference, ctx.return_url, ctx.cancel_url], ['VESPR', 'NO_SHIPPING', 'LOGIN', 'PAY_NOW', 'IMMEDIATE_PAYMENT_REQUIRED', ORDER.returnUrl, ORDER.cancelUrl], 'the same experience context as the fetch client')
  ok(/^Basic /.test(calls[0].headers.authorization) && /^Bearer /.test(c.headers.authorization), 'basic auth for the token, bearer for the order')
  const again = await p.createOrder({ ...ORDER, referenceId: 'ref-1', customId: 'cust-1' }); eq(again.id, o.id, 'the same PayPal-Request-Id returns the same order'); eq(fake.state.creates, 1)
  for (const [bad, why] of [[{ cents: 0 }, 'zero'], [{ cents: 12.5 }, 'fraction'], [{ currency: 'usd' }, 'currency'], [{ requestId: '' }, 'no request id'], [{ returnUrl: 'javascript:alert(1)' }, 'js url'], [{ cancelUrl: 'nope' }, 'bad cancel']]) { const q = fresh(); await rej(q.createOrder({ ...ORDER, ...bad }), 'bad_request', why); eq(calls.length, 0, 'nothing sent for ' + why) }
}
// get, capture, refund: the same flat answers, the amount from the capture when the unit has none (as the real sandbox does)
{
  const p = fresh(); const o = await p.createOrder(ORDER)
  eq(await p.getOrder(o.id), { id: o.id, status: 'PAYER_ACTION_REQUIRED', value: '25.00', currency: 'USD', customId: ORDER.requestId, referenceId: ORDER.requestId, captureId: '', captureStatus: '' })
  const early = await rej(p.captureOrder(o.id, { requestId: 'vespr-cap-0123456789abcdef' }), 'order_not_approved', 'a capture before the buyer approves is refused by PayPal'); ok(/has not approved/.test(early.message)); eq(fake.state.captures, 0)
  fake.approve(o.id); const cap = await p.captureOrder(o.id, { requestId: 'vespr-cap-0123456789abcdef' })
  eq(cap, { id: o.id, status: 'COMPLETED', value: '25.00', currency: 'USD', customId: ORDER.requestId, referenceId: ORDER.requestId, captureId: cap.captureId, captureStatus: 'COMPLETED' }); ok(/^FAKECAP/.test(cap.captureId))
  const rc = apiCalls().filter(c => /\/capture$/.test(c.path)); eq(rc.map(c => c.headers['paypal-request-id']), ['vespr-cap-0123456789abcdef', 'vespr-cap-0123456789abcdef'], 'the idempotency key on capture'); eq(rc[1].path, `/v2/checkout/orders/${o.id}/capture`)
  eq((await p.captureOrder(o.id, { requestId: 'vespr-cap-0123456789abcdef' })).captureId, cap.captureId, 'the same capture request id returns the same capture'); eq(fake.state.captures, 1)
  const ref = await p.refundCapture(cap.captureId, { requestId: 'vespr-ref-0123456789abcdef', cents: 2500, currency: 'USD', note: 'VESPR sandbox\nrefund' }); eq(ref.status, 'COMPLETED'); ok(/^FAKEREF/.test(ref.id))
  const rcall = apiCalls().filter(c => /\/refund$/.test(c.path)).pop(); eq([rcall.path, rcall.headers['paypal-request-id']], [`/v2/payments/captures/${cap.captureId}/refund`, 'vespr-ref-0123456789abcdef']); eq(JSON.parse(rcall.body), { amount: { currency_code: 'USD', value: '25.00' }, note_to_payer: 'VESPR sandbox refund' })
  eq((await p.refundCapture(cap.captureId, { requestId: 'vespr-ref-0123456789abcdef', cents: 2500 })).id, ref.id, 'the same refund request id returns the same refund'); await rej(p.refundCapture(cap.captureId, { requestId: 'another-ref-id', cents: 2500 }), 'already_refunded', 'a second refund is refused'); eq(fake.state.refunds, 1)
  for (const bad of ['', 'a/b', '../x', null]) { await rej(p.getOrder(bad), 'bad_request', 'order id ' + bad); await rej(p.captureOrder(bad), 'bad_request') }
  await rej(p.refundCapture('CAP1234567', { cents: 0 }), 'bad_request'); await rej(p.refundCapture('CAP1234567', { cents: 100, currency: 'usd' }), 'bad_request'); await rej(p.refundCapture('a/b', { cents: 100 }), 'bad_request')
}
// PayPal's failures arrive as the same codes the payment flow acts on
{
  const rec = async (reply, call, code, m) => { const p = fresh(); const o = await p.createOrder(ORDER); fake.state.failNext.push({ match: /./, reply }); await rej(call(p, o), code, m) }
  await rec({ status: 422, json: { details: [{ issue: 'INSTRUMENT_DECLINED' }] } }, (p, o) => p.captureOrder(o.id), 'declined', '422 INSTRUMENT_DECLINED')
  await rec({ status: 422, json: { details: [{ issue: 'SOMETHING_NEW' }] } }, (p, o) => p.captureOrder(o.id), 'rejected', '422 unknown issue')
  await rec({ status: 404, json: { name: 'RESOURCE_NOT_FOUND' } }, (p, o) => p.getOrder(o.id), 'not_found', '404')
  await rec({ status: 500, json: { name: 'INTERNAL_SERVER_ERROR' } }, (p, o) => p.getOrder(o.id), 'unavailable', '500')
  const bad = createSdkPayPal({ clientId: ID, clientSecret: 'wrong-' + SECRET, transport: adapterFor(createFakePayPal({ clientId: ID, clientSecret: SECRET })), log: m => logs.push(m) }); const e = await rej(bad.createOrder(ORDER), 'bad_credentials', 'a refused client id and secret'); eq(e.message, 'PayPal refused the sandbox client id and secret.')
  const down = createSdkPayPal({ clientId: ID, clientSecret: SECRET, transport: async () => { const x = new Error('socket hang up ' + SECRET); x.code = 'ECONNRESET'; throw x }, log: m => logs.push(m) }); const ne = await rej(down.getOrder('ORDER1234567890AB'), 'network', 'a network error'); eq(ne.message, 'Could not reach PayPal.')
}
// the credentials never appear in a log, an error or a result
{
  logs.length = 0; const outputs = []; const p = fresh({ log: m => logs.push(m) }); const o = await p.createOrder(ORDER); outputs.push(JSON.stringify(o)); fake.state.failNext.push({ match: /./, reply: { status: 422, json: { details: [{ issue: 'ORDER_NOT_APPROVED', description: 'echo ' + SECRET }], debug_id: 'dbgS' } } })
  try { await p.captureOrder(o.id) } catch (e) { outputs.push(e.message, JSON.stringify(e)) }
  const w = createSdkPayPal({ clientId: ID, clientSecret: 'wrong-' + SECRET, transport: adapterFor(createFakePayPal({ clientId: ID, clientSecret: SECRET })), log: m => logs.push(m) }); try { await w.getOrder('ORDER1234567890AB') } catch (e) { outputs.push(e.message, JSON.stringify(e)) }
  const all = [...logs, ...outputs].join('\n'); for (const s of [SECRET, ID, 'wrong-', 'fake-token', Buffer.from(`${ID}:${SECRET}`).toString('base64')]) ok(!all.includes(s), 'not in any log or error: ' + s.slice(0, 10))
  ok(logs.every(l => /^paypal\(sdk\): /.test(l) && l.length < 200), 'short, prefixed log lines'); ok(logs.some(l => /ORDER_NOT_APPROVED/.test(l) && /debug_id dbgS/.test(l)))
}
console.log(`paypal sdk driver tests passed (${n}): the same interface, requests, error codes and idempotency as the fetch client, sandbox only, no credentials in logs or errors (PayPal's server SDK, no network)`)
process.exit(0)
